import subprocess
import re

def get_n():
    cmd = 'openssl rsa -pubin -in public.pem -modulus'
    output = subprocess.check_output(cmd, shell=True).decode()
    # The modulus is usually on a line starting with 'Modulus:'
    # And it's in hexadecimal.
    lines = output.splitlines()
    for line in lines:
        if 'Modulus:' in line:
            hex_str = line.split(':')[1].strip()
            return int(hex_str, 16)
    return None

n = get_n()
if n:
    print(n)
else:
    print('Failed to find n')
"
